import {POTION_BUFF_KEYS} from './potion-catalog.js';
import {POTIONS,RARITY,potionEntries,parsePotionKey,potionEffect,resolvePotionKey} from './engine.js';
import {icon} from './icons.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const remaining=(end,now)=>Math.max(0,Math.ceil((Number(end)-now)/1000)||0);
const qualityClass=p=>Number.isInteger(p?.quality)&&p.quality>=0&&p.quality<=3?'potionQ'+p.quality:'';
const qualityTitle=p=>p?.qualityName?' · '+p.qualityName:'';
const clock=seconds=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
const elementNames={earth:'地',water:'水',fire:'火',wind:'风',light:'光',dark:'暗'};
export function potionDescription(type,quality){const f=potionEffect(type,quality);if(!f)return '';if(type==='healing')return `恢复${Math.round(f.healFraction*100)}%最大生命；自动：生命不高于40%时饮用。`;const label=f.kind==='attack'?'攻击 +'+f.attack:f.kind==='luckPoints'?'幸运 +'+f.luck:f.kind==='elementAttack'?elementNames[f.element]+'元素技能增幅 +'+f.elementAttack:elementNames[f.element]+'抗性值 +'+f.elementResistance;return label+'，持续5分钟；同品质延长时长，高品质替换，低品质不消耗。';}
/** Pure renderer. Times are epoch milliseconds; potions/buffs contain display-ready descriptions. */
export function renderPotionPanel(s,{potions=[],selected=null,auto=false,now=Date.now(),cooldownUntil=0,buffs=[],restUntil=0}={}){
 const carried=potions.find(p=>p.id===selected),rest=remaining(restUntil,now),cooldown=remaining(cooldownUntil,now),active=buffs.filter(b=>remaining(b.endAt,now)>0),count=Math.max(0,Number(carried?.count)||0),disabled=rest>0||cooldown>0||!carried||count<1;
 const action=rest?`休整 ${clock(rest)}`:cooldown?`冷却 ${clock(cooldown)}`:!carried?'选择药剂':count<1?'药剂不足':'饮用';
 return `<section class="potionPanel" aria-label="药剂携带与饮用"><div class="potionTop"><div class="potionCarry ${carried?'is-filled':''} ${qualityClass(carried)}" title="独立药剂栏：同时携带一种药剂${esc(qualityTitle(carried))}"><span class="potionCarryIcon">${carried?icon(carried.icon||'potionHeal'):'<span class="potionEmpty">+</span>'}</span><div><span class="potionEyebrow">药剂栏</span><strong>${carried?esc(carried.name):'未携带'}</strong><small>${carried?'库存 ×'+count:'选择一种药剂'}</small></div></div><div class="potionActions"><button type="button" class="potionAuto ${auto?'is-on':''}" data-potionauto="1" aria-pressed="${auto?'true':'false'}" title="按药剂触发条件自动饮用"><span class="potionSwitch" aria-hidden="true"></span>自动</button><button type="button" class="primary potionDrink" data-potiondrink="1" ${disabled?'disabled':''} ${rest?'title="休整结束前不能饮用药剂"':''}>${action}</button></div></div><div class="potionStock" aria-label="选择携带药剂">${potions.map(p=>`<button type="button" class="potionStockItem ${selected===p.id?'is-selected':''} ${qualityClass(p)}" data-potionselect="${esc(p.id)}" aria-pressed="${selected===p.id?'true':'false'}" title="${esc((p.description||p.name)+qualityTitle(p))}" aria-label="${esc(p.name+qualityTitle(p))}">${icon(p.icon||'potionHeal')}<span><strong>${esc(p.name)}</strong><small>×${Math.max(0,Number(p.count)||0)}</small></span></button>`).join('')}</div>${carried?.description?`<p class="potionDescription">${esc(carried.description)}</p>`:''}${active.length?`<div class="potionBuffs" aria-label="当前药剂效果">${active.map(b=>`<div class="potionBuff" title="${esc(b.description||b.name)}">${icon(b.icon||'potionPower')}<span>${esc(b.name)}</span><b>${clock(remaining(b.endAt,now))}</b></div>`).join('')}</div>`:''}<div class="potionFootnote">共用 10 秒饮用冷却<span>${rest?'休整中仍可更换携带药剂':'同类增益延长时间，不叠加强度'}</span></div></section>`;
}

export function renderBattlePotionButton(s,now=Date.now()){const key=resolvePotionKey(s,now),chosen=parsePotionKey(key||s.potionSlot?.key),type=chosen?.type,rows=potionEntries(s).filter(p=>p.type===type),count=rows.reduce((n,p)=>n+p.count,0),cd=remaining(s.potionReadyAt,now);return `<button class="battlePotionButton ${chosen?'potionQ'+chosen.quality:''}" data-potion-settings="1" title="药剂设置 · 共用10秒冷却" aria-label="药剂设置，库存${count}，冷却${cd}秒">${icon(POTIONS[type]?.icon||'potionHeal')}<b>×${count}</b>${cd?`<span class="battlePotionShade" style="--cooldown:${Math.min(1,cd/10)}"><strong>${cd}s</strong></span>`:''}</button>`;}
export function renderPotionSettings(s){const now=Math.max(Date.now(),s.lastHealthClock||0),key=resolvePotionKey(s,now),chosen=parsePotionKey(key||s.potionSlot?.key),rows=potionEntries(s),potions=rows.map(p=>{const effect=potionEffect(p.type,p.quality);return {id:p.key,name:POTIONS[p.type].name,icon:POTIONS[p.type].icon,count:p.count,quality:p.quality,qualityName:RARITY[p.quality],description:potionDescription(p.type,p.quality)};});return `<h2>随身药剂</h2><div class="potionTypeChoices">${Object.entries(POTIONS).map(([type,p])=>`<button data-potion-type="${type}" aria-pressed="${chosen?.type===type}">${icon(p.icon)}${esc(p.name)}</button>`).join('')}</div><div class="potionPriorityChoices"><button data-potion-priority="low" aria-pressed="${s.potionSlot?.priority!=='high'}">低品质优先</button><button data-potion-priority="high" aria-pressed="${s.potionSlot?.priority==='high'}">高品质优先</button></div>${renderPotionPanel(s,{potions,selected:key,auto:s.potionSlot?.auto,now,cooldownUntil:s.potionReadyAt,restUntil:s.restUntil,buffs:POTION_BUFF_KEYS.map(type=>({id:type,name:POTIONS[type].name,icon:POTIONS[type].icon,endAt:s.potionBuffs?.[type]?.endAt||0,description:potionDescription(type,s.potionBuffs?.[type]?.quality??0)}))})}<p class="potionDescription">同类型药剂按优先级选用，不切换其他类型；已有更强增益时跳过低品质。出发前备药。</p>`;}
